#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: manual setup for the AWS account, the OIDC roles, the GitHub
# variables and the `production` Environment that .github/workflows/deploy.yml needs.
# Resumable: a finished stage is recorded in $STATE_FILE and skipped on re-run
# (`--reset` forgets them). Values are also kept in .env, offered as defaults.
# The gate secrets, branch-protection check, SNS and Billing tag stay in
# scripts/wizard-post-merge-setup.sh.
# ──────────────────────────────────────────────────────────────────────────

STATE_FILE="${WIZARD_STATE:-.wizard-setup.state}"

run_wizard() {

TOTAL_STAGES=6

is_done() { grep -qxF "$1" "$STATE_FILE" 2>/dev/null; }
mark_done() { is_done "$1" || printf '%s\n' "$1" >>"$STATE_FILE"; }

# begin ID "Name": opens the stage, or reports it as done and returns 1 to skip it.
begin() {
  if is_done "$1"; then
    _STAGE_INDEX=$((_STAGE_INDEX + 1))
    printf '  %s✓ stage %s/%s already done:%s %s\n' "$GREEN" "$_STAGE_INDEX" "$TOTAL_STAGES" "$RESET" "$2"
    return 1
  fi
  stage "$2"
}

# aws_ready loops until the AWS CLI has working credentials.
aws_ready() {
  until aws sts get-caller-identity >/dev/null 2>&1; do
    warn "no working AWS credentials in this shell."
    step "Log in (aws sso login, aws configure, or export the AWS_* variables), then retry."
    pause "Logged in? Press Enter to check again."
  done
}

# A resumed run skips the stages that asked for these, so reload them from .env.
for key in BUCKET_SUFFIX ALERT_EMAIL AWS_REGION GEMINI_API_KEY; do
  value=$(_existing "$key" || true)
  [[ -n "$value" ]] && printf -v "$key" '%s' "$value"
done

if [[ "${1:-}" == "--reset" ]]; then
  rm -f "$STATE_FILE"
  note "forgot the finished stages in $STATE_FILE"
fi

banner "Deploy setup: AWS account, OIDC roles, GitHub variables, production Environment"

if begin aws "AWS account and bucket suffix"; then
  say "The state bucket and every S3 name carry BUCKET_SUFFIX (3-20 chars of a-z, 0-9, -)."
  command -v aws >/dev/null 2>&1 || { warn "install the AWS CLI first"; exit 1; }
  command -v terraform >/dev/null 2>&1 || { warn "install terraform >= 1.10 first"; exit 1; }
  aws_ready
  say "Signed in as: $(aws sts get-caller-identity --query Arn --output text)"
  ask BUCKET_SUFFIX "BUCKET_SUFFIX (for example your account id):"
  write_env BUCKET_SUFFIX "$BUCKET_SUFFIX"
  write_env AWS_REGION "${AWS_REGION:-us-east-1}"
  mark_done aws
fi

if begin alert "Alert email"; then
  say "Alarms and budget notices go to ALERT_EMAIL; deploy.yml reads it as a secret."
  ask ALERT_EMAIL "Email that receives alarms and budget notices:"
  write_env ALERT_EMAIL "$ALERT_EMAIL"
  set_secret ALERT_EMAIL "$ALERT_EMAIL"
  mark_done alert
fi

if begin bootstrap "Bootstrap: state bucket and GitHub OIDC roles"; then
  say "Applies infra/bootstrap with local state: the state bucket, the GitHub OIDC"
  say "provider and the plan and deploy roles. Safe to repeat; it only adds what is missing."
  aws_ready
  note "The OIDC provider is detected from the state and the account; nothing to answer."
  if confirm "Run scripts/deploy-infra.sh bootstrap now?"; then
    BUCKET_SUFFIX="$BUCKET_SUFFIX" ALERT_EMAIL="$ALERT_EMAIL" AWS_REGION="${AWS_REGION:-us-east-1}" \
      scripts/deploy-infra.sh bootstrap
    mark_done bootstrap
  else
    SKIPPED+=("bootstrap: scripts/deploy-infra.sh bootstrap (then re-run this wizard)")
    exit 0
  fi
fi

if begin vars "GitHub repository variables"; then
  say "deploy.yml reads AWS_PLAN_ROLE_ARN, AWS_DEPLOY_ROLE_ARN, BUCKET_SUFFIX and TF_STATE_BUCKET."
  boot=(terraform -chdir=infra/bootstrap output -raw)
  set_var AWS_PLAN_ROLE_ARN "$("${boot[@]}" plan_role_arn)"
  set_var AWS_DEPLOY_ROLE_ARN "$("${boot[@]}" deploy_role_arn)"
  set_var TF_STATE_BUCKET "$("${boot[@]}" state_bucket)"
  set_var BUCKET_SUFFIX "$BUCKET_SUFFIX"
  mark_done vars
fi

if begin environment "GitHub Environment: production"; then
  say "Apply waits for a required reviewer, and only master may deploy to it."
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    repo=$(gh repo view --json nameWithOwner -q .nameWithOwner)
    uid=$(gh api user -q .id)
    say "Reviewer: $(gh api user -q .login) (you), on $repo"
    if confirm "Create or update the production Environment now?"; then
      policy='"deployment_branch_policy":{"protected_branches":false,"custom_branch_policies":true}'
      reviewers=ok
      printf '{"reviewers":[{"type":"User","id":%s}],%s}' "$uid" "$policy" |
        gh api -X PUT "repos/${repo}/environments/production" --input - >/dev/null || reviewers=missing
      if [[ "$reviewers" == missing ]]; then
        # Private repos on a free plan cannot have required reviewers (HTTP 422).
        warn "required reviewers are not available for this repository on its plan."
        printf '{%s}' "$policy" | gh api -X PUT "repos/${repo}/environments/production" --input - >/dev/null
        SKIPPED+=("production has NO approval gate: make the repo public or upgrade the plan, then re-run this wizard")
      fi
      # 422 when the master policy already exists: fine on a re-run.
      gh api -X POST "repos/${repo}/environments/production/deployment-branch-policies" \
        -f name=master -f type=branch >/dev/null 2>&1 || true
      if [[ "$reviewers" == ok ]]; then
        say "✓ production: required reviewer set, deployments limited to master"
        mark_done environment
      else
        say "production: deployments limited to master, but nobody has to approve them"
      fi
    else
      SKIPPED+=("Environment production: required reviewers and master as the only deployment branch")
    fi
  else
    open_url "https://github.com/$(git remote get-url origin | sed -E 's#.*github.com[:/]##; s#\.git$##')/settings/environments"
    step "New environment 'production' > Required reviewers: add yourself."
    step "Deployment branches and tags > Selected branches > add 'master'."
    pause "Done? Press Enter."
    mark_done environment
  fi
fi

if begin gemini "Gemini runtime key"; then
  say "The deployed worker reads the key from SSM. deploy-infra.sh up writes GEMINI_API_KEY"
  say "there on a local deploy; the CI deploy never touches it. Use a key apart from the gate's."
  open_url "https://aistudio.google.com/apikey"
  ask_secret GEMINI_API_KEY "Paste the runtime Gemini API key:"
  write_env GEMINI_API_KEY "$GEMINI_API_KEY"
  param="/invoice-extraction-prod/gemini-api-key"
  if aws ssm get-parameter --name "$param" >/dev/null 2>&1 && confirm "Parameter $param exists. Overwrite it now?"; then
    printf %s "$GEMINI_API_KEY" | aws ssm put-parameter --overwrite --type SecureString \
      --name "$param" --value file:///dev/stdin >/dev/null
    say "✓ wrote $param"
  else
    note "Not in SSM yet: run the first deploy locally with scripts/deploy-infra.sh up."
  fi
  mark_done gemini
fi

note "Gate secrets, branch protection, SNS and Billing tag: scripts/wizard-post-merge-setup.sh"
finish
}

run_wizard "$@"; exit
